"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["73152"],{28123(e){e.exports=JSON.parse('{"id":"F061","slug":"trial-balance","name":"Debits Equal Credits (Trial Balance)","subject":"Finance Foundations","section":"Accounting Basics","topic":"Double-entry bookkeeping","level":"Beginner","aliases":["trial balance check","double entry check","debit credit rule"],"formula":{"latex":"\\\\sum \\\\text{Debits}=\\\\sum \\\\text{Credits}","also":[],"text":"Total debits = Total credits"},"symbols":[{"symbol":"Debits","meaning":"Entries on the left side of an account. They increase assets and expenses, and reduce liabilities, equity and revenue","unit":"money"},{"symbol":"Credits","meaning":"Entries on the right side of an account. They increase liabilities, equity and revenue, and reduce assets and expenses","unit":"money"}],"when_to_use":"Use it as the basic check on bookkeeping. After recording every transaction, total debits must equal total credits. If they do not, there is an error to find.","worked_example":{"problem":"A trial balance lists debit balances of 600 (cash), 400 (equipment) and 350 (expenses), and credit balances of 400 (loan), 500 (capital) and 450 (revenue). Do the totals agree?","inputs":{"debits":[600,400,350],"credits":[400,500,450]},"steps":[{"label":"Total debits","working":null,"value":"1,350.00"},{"label":"Total credits","working":null,"value":"1,350.00"},{"label":"Difference = debits - credits","working":"1350-1350","value":"0.00"}],"answer":"Total debits are 1,350.00 and total credits are 1,350.00. The difference is 0.00, so the books balance."},"calculator":{"available":false,"reason":"This is a rule for checking entries rather than a calculation. A learner checks it by adding two columns, so a calculator adds nothing.","spec_if_wanted_later":{"available":true,"inputs":[{"id":"debits","label":"Debit balances","unit":"money","type":"list","default":[600,400,350],"hint":""},{"id":"credits","label":"Credit balances","unit":"money","type":"list","default":[400,500,450],"hint":""}],"checks":[],"steps":[{"id":"d","label":"Total debits","expr":"sum(debits)","format":"money"},{"id":"c","label":"Total credits","expr":"sum(credits)","format":"money"},{"id":"diff","label":"Difference = debits - credits","expr":"d-c","format":"money"}],"results":["d","c","diff"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"d":1350,"c":1350,"diff":0}}},"finder":{"finds":"Whether the books balance","needs":"Debit balances, credit balances"},"related":[{"slug":"expanded-accounting-equation","name":"Expanded Accounting Equation"},{"slug":"accounting-equation","name":"The Accounting Equation"}],"related_ids":["F062","F063"],"group":"Foundations","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mo>\u2211</mo><mtext>Debits</mtext><mo>=</mo><mo>\u2211</mo><mtext>Credits</mtext></mrow><annotation encoding=\\"application/x-tex\\">\\\\sum \\\\text{Debits}=\\\\sum \\\\text{Credits}</annotation></semantics></math></span>","lines":[{"lhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>\u2211</mo><mtext>Debits</mtext></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle \\\\sum \\\\text{Debits}</annotation></semantics></math></span>","rhs":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\"><semantics><mrow><mstyle scriptlevel=\\"0\\" displaystyle=\\"true\\"><mo>=</mo><mo>\u2211</mo><mtext>Credits</mtext></mstyle></mrow><annotation encoding=\\"application/x-tex\\">\\\\displaystyle =\\\\sum \\\\text{Credits}</annotation></semantics></math></span>"}],"alsoMathml":[],"prev":{"slug":"dcf-enterprise-value","name":"DCF Enterprise Value (Explicit Period plus Terminal Value)"},"next":{"slug":"debt-ratio","name":"Debt Ratio"},"lesson":null,"total":522}')}}]);